var e={id:`fire-slags-joder`,episode:19,door:19,title:{nb:`Fire slags jøder`,en:`Four kinds of Jews`},reference:`Luk 20,27–40; Apg 23,6–8`,place:`jerusalem`,prologue:[{image:`maps/jerusalem-gate.webp`,text:{nb:`Teofilos er greker. Når Lukas skriver «fariseer» og «saddukeer», må han forklare. Du har hørt dem ved templet før; nå må Lukas finne ut hva som skiller dem.`,en:`Theophilus is a Greek. When Luke writes “Pharisee” and “Sadducee”, he must explain. You heard them by the temple before; now Luke must work out what divides them.`}},{image:`art/lukas.webp`,text:{nb:`Fire slags jøder, sier Josefus, en ung prest i Jerusalem. Og mange står utenfor alle fire. Hvor passet Jesus inn?`,en:`Four kinds of Jews, says Josephus, a young priest in Jerusalem. And many stand outside all four. Where did Jesus fit in?`}}],intro:{nb:`Tempelforgården i Jerusalem, full av folk av alle slag.`,en:`The temple court in Jerusalem, full of people of every kind.`},outro:{nb:`Prøv vitnene mot en annen kilde: de stemmer med Josefus. Og spør hvem som kunne funnet på ham: ingen av flokkene ville laget en slik Messias.`,en:`Test the witnesses against another source: they fit Josephus. And ask who could have invented him: none of the groups would have made such a Messiah.`},map:[`################################`,`################################`,`################################`,`################################`,`##########.##########.##########`,`#########.............##########`,`##############...###############`,`###############..###############`,`###############..###############`,`##############....##############`,`##############....##############`,`####.........................###`,`####........................####`,`####........................####`,`#######.....................####`,`#########...........############`,`##########..........############`,`##########..........############`,`########.#..........############`,`########............############`,`########............############`],background:`jerusalem-tempel.webp`,mood:`tense`,areas:[{id:`raadskammer`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######......########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`prestens-hus.webp`,scale:2.6,ambience:`temple`},{id:`skriverkammer`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######......########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`tempelkammer.webp`,scale:2.4,ambience:`temple`}],start:{x:11,y:5},entities:[{id:`lukas`,kind:`person`,x:9,y:5,name:{nb:`Lukas`,en:`Luke`},look:`luke`,portrait:`lukas.webp`,interactions:[{not:[`oppdrag`],say:[{nb:`Hør fariseeren, saddukeeren, esseneren og den unge ved porten. Så tolleren, samaritanen og grekeren. Til slutt rådskammeret og skriverkammeret.`,en:`Hear the Pharisee, Sadducee, Essene and the young man. Then the tax collector, Samaritan and Greek. Last, the council and scribe’s chambers.`}],set:[`oppdrag`]},{has:[`fire-lost`,`oppstandelsen-lost`,`de-andre-lost`,`mot-josefus-lost`,`passet-ikke-lost`,`raadet-lost`],not:[`avsluttet`],say:[{nb:`Nå forstår jeg stridene bedre: om oppstandelsen, om sabbaten, om hvem som får sitte til bords.`,en:`Now I understand the quarrels better: the resurrection, the sabbath, who may sit at table.`},{nb:`I morgen legger vi det jeg skriver ved siden av det menigheten i Antiokia forteller om fødselen.`,en:`Tomorrow we lay what I write beside what the church in Antioch says about the birth.`}],set:[`avsluttet`]},{has:[`spor:josefus`],not:[`fire-lost`],say:[{nb:`Når du har nok, kommer jeg med sakene.`,en:`When you have enough, I will bring you the cases.`}]},{say:[{nb:`Fariseeren, saddukeeren, esseneren, den unge. Tolleren, samaritanen, grekeren. Rådskammeret og skriverkammeret.`,en:`The Pharisee, the Sadducee, the Essene, the young man. The tax collector, the Samaritan, the Greek. The council chamber and the scribe’s chamber.`}]}]},{id:`dor-raadskammer`,kind:`place`,x:10,y:4,name:{nb:`Rådskammeret`,en:`The council chamber`},look:`hotspot`,door:{area:`raadskammer`,x:15,y:14}},{id:`dor-skriverkammer`,kind:`place`,x:21,y:4,name:{nb:`Skriverkammeret`,en:`The scribe’s chamber`},look:`hotspot`,door:{area:`skriverkammer`,x:15,y:14}},{id:`fariseer`,kind:`person`,x:14,y:6,name:{nb:`Fariseeren`,en:`The Pharisee`},look:`scribe`,portrait:`scribe.webp`,interactions:[{has:[`oppdrag`],not:[`spor:fariseer`],say:[{nb:`Vi er de atskilte, det betyr navnet. Vi holder loven med gjerder rundt: sabbaten, tienden, rene hender. Hele folket skal være hellig.`,en:`Our name means the separated ones. We keep the law with a fence around it: the sabbath, the tithe, clean hands. The whole people is to be holy.`},{nb:`Vi tror på oppstandelsen, på engler og på dommen, og folket hører på oss.`,en:`We believe in the resurrection, angels and the judgement, and the people listen to us.`},{nb:`Jesus fra Nasaret? Han spiste hos oss, og hos tollere. Han sa at vi vasket utsiden av begeret. Det sved. Noen av oss fulgte ham likevel.`,en:`Jesus of Nazareth? He ate with us, and with tax collectors. He said we washed only the outside of the cup. That stung. Yet some of us followed him.`}],set:[`spor:fariseer`,`spor:fariseer-jesus`,`fakta:fariseere`]},{has:[`innbydelser`],not:[`svar:fariseer`],say:[{nb:`Spise hos en toller? Aldri.`,en:`Eat at a tax collector’s? Never.`}],set:[`svar:fariseer`]},{not:[`oppdrag`],say:[{nb:`Snakk med Lukas først.`,en:`Speak with Luke first.`}]},{say:[{nb:`Hele folket skal være hellig. Ved hvert bord.`,en:`The whole people is to be holy. At every table.`}]}]},{id:`saddukeer`,kind:`person`,x:24,y:12,name:{nb:`Saddukeeren`,en:`The Sadducee`},look:`scribe`,portrait:`scribe.webp`,interactions:[{has:[`oppdrag`],not:[`spor:saddukeer`],say:[{nb:`Vi er prestefamiliene; templet er vårt. Moses’ fem bøker går foran alt, og fariseernes «fedrenes tradisjon» er menneskepåfunn.`,en:`We are the priestly families; the temple is ours. Moses’ five books come first; the Pharisees’ “tradition of the fathers” is human invention.`},{nb:`Oppstandelse? Det står ikke hos Moses. Engler og ånder: nei. Og vi holder fred med Roma, ellers mister vi templet.`,en:`Resurrection? It is not in Moses. Angels and spirits: no. And we keep peace with Rome, or we lose the temple.`},{nb:`Vi prøvde ham med en gåte om sju brødre og én kone. Han svarte fra tornebusken hos Moses: Abrahams Gud er ikke de dødes Gud. Vi hadde ikke noe svar.`,en:`We tested him with a riddle: seven brothers, one wife. He answered from the burning bush in Moses: Abraham’s God is not a God of the dead. We had no answer.`}],set:[`spor:saddukeer`,`spor:gaaten`,`fakta:saddukeere`]},{has:[`innbydelser`],not:[`svar:saddukeer`],say:[{nb:`Jeg bruker ham. Jeg spiser ikke med ham.`,en:`I use him. I do not eat with him.`}],set:[`svar:saddukeer`]},{say:[{nb:`Moses’ fem bøker. Og fred med Roma.`,en:`The five books of Moses. And peace with Rome.`}]}]},{id:`essener`,kind:`person`,x:17,y:12,name:{nb:`Esseneren`,en:`The Essene`},look:`beggar`,portrait:`beggar.webp`,interactions:[{has:[`oppdrag`],not:[`spor:essener`],say:[{nb:`Vi har forlatt templet, for prestene her er urene, og kalenderen deres er feil. Vi bor sammen, deler alt og renser oss hver dag.`,en:`We have left the temple: the priests here are impure and their calendar is wrong. We live together, share everything and wash every day.`},{nb:`Vi venter på to salvede, en prest og en konge. En spedalsk eller en lam får ikke sitte ved bordet vårt.`,en:`We wait for two anointed ones, a priest and a king. No leper or lame man may sit at our table.`},{nb:`Han fra Nasaret? Han rørte ved spedalske og kalte lamme og blinde til bords. Det motsatte av oss.`,en:`The one from Nazareth? He touched lepers and called the lame and the blind to the table. The opposite of us.`}],set:[`spor:essener`,`spor:essener-jesus`,`fakta:essenere`]},{has:[`innbydelser`],not:[`svar:essener`],say:[{nb:`Uren. Si ham det.`,en:`Unclean. Tell him so.`}],set:[`svar:essener`]},{has:[`spor:sol`,`spor:maane`],not:[`kalender-sett`],say:[{nb:`Derfor holder prestene høytidene på feil dag, etter vår regning.`,en:`That is why the priests keep the feasts on the wrong day, by our reckoning.`}],set:[`kalender-sett`]},{say:[{nb:`Renhet først. Han gjorde det motsatte.`,en:`Purity first. He did the opposite.`}]}]},{id:`ung`,kind:`person`,x:27,y:12,name:{nb:`Den unge ved porten`,en:`The young man at the gate`},look:`boy`,portrait:`boy.webp`,interactions:[{has:[`oppdrag`],not:[`spor:ung`],say:[{nb:`Ingen herre uten Gud. Judas fra Galilea sa det da keiseren ville telle oss. Å betale skatt til keiseren er å kalle ham herre.`,en:`No lord but God. Judas of Galilee said it when the emperor counted us. Paying tax to the emperor means calling him lord.`},{nb:`Vi venter ikke på salvede fra ørkenen. Vi venter på dagen vi tar sverdet.`,en:`We do not wait for anointed ones from the desert. We wait for the day we take the sword.`},{nb:`De spurte ham om skatten. Han så på keiserens bilde på mynten: gi keiseren det som er keiserens, og Gud det som er Guds. Hva han mente, vet jeg ikke.`,en:`They asked him about the tax. Looking at the emperor’s face on the coin, he said: give the emperor what is his, and God what is God’s. I do not know what he meant.`}],set:[`spor:ung`,`spor:skatten`,`fakta:fjerde`]},{has:[`innbydelser`],not:[`svar:ung`],say:[{nb:`Forræder. Han tar romernes penger.`,en:`Traitor. He takes the Romans’ money.`}],set:[`svar:ung`]},{say:[{nb:`Ingen herre uten Gud. Ikke keiseren.`,en:`No lord but God. Not the emperor.`}]}]},{id:`toller`,kind:`person`,x:12,y:12,name:{nb:`Tolleren`,en:`The tax collector`},look:`trader`,portrait:`trader.webp`,interactions:[{has:[`oppdrag`],not:[`spor:toller`],say:[{nb:`Jeg hører ikke til noen av dem. Fariseeren spiser ikke med meg, saddukeeren bruker meg, og den unge der vil drepe meg.`,en:`I belong to none of them. The Pharisee won’t eat with me, the Sadducee uses me, and that young man wants to kill me.`},{nb:`Så sa en til Levi i Kapernaum: følg meg, og spiste i huset hans med oss alle. Fariseerne spurte hvorfor. Han sa: de syke trenger lege.`,en:`Then someone said to Levi in Capernaum: follow me, and ate in his house with all of us. The Pharisees asked why. He said: the sick need a doctor.`}],set:[`spor:toller`]},{has:[`svar:fariseer`,`svar:saddukeer`,`svar:essener`,`svar:ung`],not:[`ingen-kom`],say:[{nb:`Ingen kom. Han kom.`,en:`None of them came. He came.`}],set:[`ingen-kom`]},{has:[`spor:toller`],not:[`innbydelser`],say:[{nb:`Fire innbydelser til bords hos meg. Bær dem til fariseeren, saddukeeren, esseneren og den unge ved porten, og hør svarene.`,en:`Four invitations to my table. Take them to the Pharisee, the Sadducee, the Essene and the young man at the gate, and hear their answers.`}],set:[`innbydelser`]},{say:[{nb:`De syke trenger lege. Det var oss.`,en:`The sick need a doctor. That was us.`}]}]},{id:`samaritan`,kind:`person`,x:5,y:11,name:{nb:`Samaritanen`,en:`The Samaritan`},look:`courier`,portrait:`courier.webp`,interactions:[{has:[`oppdrag`],not:[`spor:samaritan`],say:[{nb:`Vårt tempel sto på Garisim, til jødene rev det ned. Vi har bare Moses’ fem bøker, og jødene kaller oss fremmede.`,en:`Our temple stood on Gerizim until the Jews tore it down. We keep only Moses’ five books, and the Jews call us foreigners.`},{nb:`Han fra Nasaret gikk gjennom landet vårt. En landsby avviste ham, og disiplene ville rope ned ild. Han sa nei.`,en:`The one from Nazareth walked through our land. A village turned him away; his disciples wanted to call down fire. He said no.`},{nb:`Og han fortalte en historie der en samaritan var den gode.`,en:`And he told a story where a Samaritan was the good one.`}],set:[`spor:samaritan`,`fakta:samaritanere`]},{say:[{nb:`En samaritan var den gode. Det har jeg aldri hørt fra en jøde før.`,en:`A Samaritan was the good one. I have never heard that from a Jew before.`}]}]},{id:`greker`,kind:`person`,x:19,y:12,name:{nb:`Den gudfryktige grekeren`,en:`The God-fearing Greek`},look:`potter`,portrait:`potter.webp`,interactions:[{has:[`oppdrag`],not:[`spor:greker`],say:[{nb:`Jeg er greker og tror på Israels Gud, men jeg er ikke omskåret. Derfor stopper jeg ved gjerdet. Lenger inn venter døden.`,en:`I am a Greek who believes in the God of Israel, but I am not circumcised. So I must stop at the barrier out there, or die.`},{nb:`Teofilos er vel en av oss? Vi vil vite om det er plass for oss.`,en:`Theophilus is one of us, I suppose? We want to know if there is room for us.`}],set:[`spor:greker`,`fakta:gudfryktige`]},{say:[{nb:`Er det plass for oss? Det er spørsmålet.`,en:`Is there room for us? That is the question.`}]}]},{id:`gutt`,kind:`person`,x:14,y:11,name:{nb:`Jenta med stjernene`,en:`The girl with the stars`},look:`girl`,portrait:`girl.webp`,interactions:[{say:[{nb:`Kan du finne stjernene i rekkefølge? Bestefar sier esseneren teller dagene etter sola og presten etter månen, og at de krangler om hvilken dag det er påske.`,en:`Can you find the stars in order? Grandfather says the Essene counts the days by the sun and the priest by the moon, and that they quarrel about which day Passover is.`}],play:{game:`stars`,title:{nb:`Finn stjernene i rekkefølge`,en:`Find the stars in order`},win:`spill-stjerner`}}]},{id:`gjerdet`,kind:`thing`,x:16,y:11,name:{nb:`Gjerdet med innskriften`,en:`The barrier with the inscription`},look:`hotspot`,interactions:[{say:[{nb:`En lav mur rundt den indre forgården, med tavler på gresk og latin: ingen fremmed innenfor, og den som tas, har seg selv å takke for døden.`,en:`A low wall around the inner court, with signs in Greek and Latin: no foreigner beyond, and anyone caught has himself to blame for his death.`}],set:[`spor:gjerdet`]}]},{id:`vei-nasaret`,kind:`place`,x:4,y:13,name:{nb:`Veien til Nasaret`,en:`The road to Nazareth`},look:`hotspot`,travelTo:`nasaret`},{id:`vei-cesarea`,kind:`place`,x:14,y:20,name:{nb:`Veien til Cæsarea`,en:`The road to Caesarea`},look:`hotspot`,travelTo:`cesarea`},{id:`dor-ut-raadskammer`,kind:`place`,x:15,y:17,name:{nb:`Ut i forgården`,en:`Out to the court`},look:`hotspot`,door:{area:`main`,x:10,y:5},area:`raadskammer`},{id:`raadsherre`,kind:`person`,x:20,y:9,name:{nb:`Rådsherren`,en:`The councillor`},look:`james`,portrait:`james.webp`,interactions:[{has:[`oppdrag`],not:[`spor:raadsherre`],say:[{nb:`Det store rådet, Sanhedrin: øverstepresten, saddukeere fra prestefamiliene og fariseere blant de skriftlærde. Sjelden enige.`,en:`The great council, the Sanhedrin: the high priest, Sadducees from the priestly families, Pharisees among the scribes. Rarely agreed.`},{nb:`Da de forhørte Paulus her, splittet han dem med ett ord: oppstandelsen.`,en:`When they questioned Paul here, he split them with one word: the resurrection.`},{nb:`Men morgenen de dømte Jesus, sto øversteprestene, de eldste og de skriftlærde samlet. Prestene fryktet for templet og Roma.`,en:`But the morning they condemned Jesus, the chief priests, the elders and scribes stood together; the priests feared for the temple and Rome.`},{nb:`Om fariseerne som flokk var med, vet jeg mindre; noen hadde advart ham. Og Josef fra Arimatea, en rådsherre, var imot dommen.`,en:`Whether the Pharisees as a group took part, I am less sure; some had warned him. And Joseph of Arimathea, a councillor, opposed the verdict.`}],set:[`spor:raadsherre`,`spor:raadet`]},{not:[`oppdrag`],say:[{nb:`Snakk med Lukas først.`,en:`Speak with Luke first.`}]},{say:[{nb:`Sjelden enige. Den morgenen var nesten alle det.`,en:`Seldom in agreement. That morning nearly all of them were.`}]}],area:`raadskammer`},{id:`benker`,kind:`thing`,x:6,y:7,name:{nb:`Halvsirkelen av benker`,en:`The half-circle of benches`},look:`hotspot`,interactions:[{say:[{nb:`Benker i halvsirkel, så alle ser hverandre. Her sitter rådets sytti og øverstepresten.`,en:`Benches in a half-circle, so everyone can see everyone. Here sit the seventy and the high priest.`}],set:[`spor:benker`]}],area:`raadskammer`},{id:`nikodemus`,kind:`thing`,x:15,y:9,name:{nb:`Setet til Nikodemus`,en:`The seat of Nicodemus`},look:`hotspot`,interactions:[{say:[{nb:`Nikodemus, en fariseer i rådet, spurte en gang: dømmer loven vår noen uten å høre ham først? De avfeide ham. Ikke alle fariseere var motstandere.`,en:`Nicodemus, a Pharisee in the council, once asked if our law condemns a man unheard. They brushed him aside. Not all Pharisees were against him.`}],set:[`spor:nikodemus`]}],area:`raadskammer`},{id:`dor-ut-skriverkammer`,kind:`place`,x:15,y:17,name:{nb:`Ut i forgården`,en:`Out to the court`},look:`hotspot`,door:{area:`main`,x:21,y:5},area:`skriverkammer`},{id:`josefus`,kind:`thing`,x:16,y:9,name:{nb:`Josefus’ oversikt`,en:`Josephus’ overview`},look:`hotspot`,interactions:[{has:[],not:[],set:[`spor:josefus`],say:[{nb:`Et ark med det Josefus fortalte meg: «Jødene har tre retninger. Fariseerne tolker loven nøyaktig og tror at sjelen lever videre.`,en:`A sheet with what Josephus told me: “The Jews have three schools. The Pharisees read the law strictly and believe the soul lives on.`},{nb:`Saddukeerne avviser det og har bare de rike med seg. Essenerne lever i fellesskap og renhet.`,en:`The Sadducees reject that and have only the rich with them. The Essenes live in community and purity.`},{nb:`Og en fjerde retning, grunnlagt av Judas fra Galilea, er som fariseerne, men vil ikke kalle noe menneske herre.»`,en:`And a fourth, founded by Judas of Galilee, is like the Pharisees but will call no man lord.”`},{nb:`Under den har jeg notert det jeg hørte dem si i forgården. Hvem av de fire sier hva? Stemmer det, kan vitnene mine prøves mot ham.`,en:`Below it I have noted what I heard them say in the court. Which of the four says what? If it holds, my witnesses can be tested against him.`}],play:{game:`bins`,title:{nb:`Hvem sier hva?`,en:`Who says what?`},win:`retningene-sortert`,data:{bins:[{nb:`Fariseeren`,en:`The Pharisee`},{nb:`Saddukeeren`,en:`The Sadducee`},{nb:`Esseneren`,en:`The Essene`},{nb:`Den fjerde`,en:`The fourth`}],cards:[{text:{nb:`De døde skal stå opp, og englene finnes.`,en:`The dead will rise, and the angels exist.`},bin:0},{text:{nb:`Fedrenes overlevering veier like tungt som det skrevne.`,en:`The tradition of the fathers weighs as much as what is written.`},bin:0},{text:{nb:`Bare Moses’ bøker gjelder. Ingen oppstandelse.`,en:`Only the books of Moses count. No resurrection.`},bin:1},{text:{nb:`Templet er vårt, og vi sitter i Rådet.`,en:`The temple is ours, and we sit in the Council.`},bin:1},{text:{nb:`Vi lever i ørkenen, deler alt og venter på to salvede.`,en:`We live in the desert, share everything and wait for two anointed ones.`},bin:2},{text:{nb:`Vi teller dagene etter sola, ikke etter prestene i Jerusalem.`,en:`We count the days by the sun, not by the priests in Jerusalem.`},bin:2},{text:{nb:`Ingen herre uten Gud. Ikke keiseren!`,en:`No lord but God. Not the emperor!`},bin:3},{text:{nb:`Sverdet mot romerne, og det nå.`,en:`The sword against the Romans, and now.`},bin:3}],ask:{nb:`Hvem ville sagt dette?`,en:`Who would have said this?`}},key:!0}}],area:`skriverkammer`},{id:`notat`,kind:`thing`,x:13,y:9,name:{nb:`Lukas’ notat`,en:`Luke’s note`},look:`hotspot`,interactions:[{say:[{nb:`Et ark: «Saddukeerne må jeg forklare for Teofilos: de avviser oppstandelsen. Fariseerne trenger ingen forklaring; de er overalt.`,en:`A sheet: “The Sadducees I must explain to Theophilus: they deny the resurrection. The Pharisees need no explaining; they are everywhere.`},{nb:`Essenerne nevner vitnene mine aldri.»`,en:`The Essenes my witnesses never mention.”`}],set:[`spor:notat`]}],area:`skriverkammer`},{id:`moses`,kind:`thing`,x:26,y:10,name:{nb:`Moses’ bøker`,en:`The books of Moses`},look:`hotspot`,interactions:[{say:[{nb:`Fem ruller. Samaritanene godtar bare disse, og saddukeerne setter dem over alt annet. Fariseerne har også profetene, salmene og fedrenes tradisjon.`,en:`Five scrolls: all the Samaritans accept, and what the Sadducees put first. The Pharisees also have the prophets, the psalms and the tradition of the fathers.`}],set:[`spor:moses`]}],area:`skriverkammer`},{id:`daniel`,kind:`thing`,x:6,y:7,name:{nb:`Rullen med Daniel`,en:`The scroll of Daniel`},look:`hotspot`,interactions:[{say:[{nb:`Daniel: de som sover i jorda, skal våkne, noen til liv, noen til skam. Her finner fariseerne oppstandelsen; saddukeerne sier at Daniel ikke er Moses.`,en:`Daniel: those who sleep in the earth will awake, some to life, some to shame. Here the Pharisees find the resurrection; the Sadducees say Daniel is not Moses.`}],set:[`spor:daniel`]}],area:`skriverkammer`},{id:`soluret`,kind:`thing`,x:8,y:13,name:{nb:`Soluret`,en:`The sundial`},look:`hotspot`,interactions:[{say:[{nb:`Esseneren teller året etter sola: 364 dager, og hver høytid faller alltid på samme ukedag.`,en:`The Essene counts the year by the sun: 364 days, and every feast always falls on the same weekday.`}],set:[`spor:sol`]}]},{id:`maanetavla`,kind:`thing`,x:26,y:14,name:{nb:`Månetavla`,en:`The moon table`},look:`hotspot`,interactions:[{say:[{nb:`Prestene teller etter månen. Måneden begynner når nymånen ses fra muren.`,en:`The priests count by the moon. The month begins when the new moon is seen from the wall.`}],set:[`spor:maane`]}]},{id:`leke-fiken`,kind:`thing`,x:8,y:18,name:{nb:`Fikenboden`,en:`The fig stall`},look:`hotspot`,interactions:[{say:[{nb:`Fikenene triller. Esseneren går i en stor bue rundt dem. Tolleren plukker opp en og spiser den.`,en:`The figs roll away. The Essene walks a wide circle round them. The tax collector picks one up and eats it.`}],fx:`tip`}]},{id:`leke-skaal`,kind:`thing`,x:10,y:16,name:{nb:`Bronseskåla på boden`,en:`The bronze bowl on the stall`},look:`hotspot`,interactions:[{say:[{nb:`Klang! Saddukeeren ser strengt på deg. Den unge mannen ved porten flirer.`,en:`Clang! The Sadducee gives you a stern look. The young man by the gate grins.`}],fx:`ring`}]},{id:`leke-kar`,kind:`thing`,x:14,y:9,name:{nb:`Vaskekaret`,en:`The washing basin`},look:`hotspot`,interactions:[{say:[{nb:`Vannet skvulper. Fariseeren nikker fornøyd: endelig en som vasker hendene.`,en:`The water splashes. The Pharisee nods with approval: at last someone who washes their hands.`}],fx:`splash`}]},{id:`leke-glod`,kind:`thing`,x:17,y:9,name:{nb:`Glødefatet`,en:`The brazier`},look:`hotspot`,interactions:[{say:[{nb:`Glørne lyser opp. Grekeren varmer hendene på avstand. Lenger inn enn gjerdet får han ikke gå.`,en:`The embers glow. The Greek warms his hands from a distance. He may not go further in than the barrier.`}],fx:`light`}]},{id:`leke-duer`,kind:`thing`,x:11,y:14,name:{nb:`Duene`,en:`The doves`},look:`hotspot`,interactions:[{say:[{nb:`Duene flyr rett over gjerdet. De bryr seg ikke om hvem som får gå hvor.`,en:`The doves fly straight over the barrier. They don’t care who may go where.`}],fx:`scatter`}]}],facts:[{id:`fariseere`,title:{nb:`Fariseerne`,en:`The Pharisees`},body:{nb:`Kort sagt: Fariseerne tok loven på alvor i hverdagen og hadde folket med seg; evangeliene og Josefus er enige om det. Navnet betyr trolig «de atskilte». Josefus (Jødenes historie 18,12–15; Krigen 2,162–163) sier de tolket loven nøyaktig, trodde på sjelens udødelighet og straff og lønn etter døden, og hadde folket med seg. De ville gjøre hele dagliglivet hellig gjennom «fedrenes tradisjon» (muntlig lov). Etter år 70 ble det deres arvtakere, rabbinerne, som formet jødedommen. Evangelienes bilde stemmer: lærere i synagogene, strenge på sabbat, tiende og renhet, tro på oppstandelsen (Apg 23,8). Men evangeliene er part i saken: de skarpe ordene (Luk 11,39–44) er sagt i strid, og Josefus, som selv hadde levd som fariseer, tegner dem mildere. Kildene er enige om læren og om innflytelsen hos folket, ikke om karakteren. Ikke alle var motstandere: Nikodemus (Joh 7,50–52), Gamaliel (Apg 5,34) og Paulus selv (Fil 3,5) var fariseere.`,en:`In short, the Pharisees took the law seriously in daily life and had the people with them; the Gospels and Josephus agree on that. The name probably means “the separated ones”. Josephus (Jewish Antiquities 18.12–15; War 2.162–163) says they interpreted the law exactly, believed in the immortality of the soul and reward and punishment after death, and had the people with them. They wanted to make all of daily life holy through “the tradition of the fathers” (oral law). After AD 70 it was their heirs, the rabbis, who shaped Judaism. The Gospels’ picture fits: teachers in the synagogues, strict on sabbath, tithe and purity, belief in the resurrection (Acts 23:8). But the Gospels are a party to the dispute: the sharp words (Luke 11:39–44) are spoken in conflict, and Josephus, who had himself lived as a Pharisee, paints them more mildly. The sources agree on the teaching and the influence with the people, not on the character. Not all were opponents: Nicodemus (John 7:50–52), Gamaliel (Acts 5:34) and Paul himself (Phil 3:5) were Pharisees.`},unlockedBy:`fakta:fariseere`},{id:`saddukeere`,title:{nb:`Saddukeerne`,en:`The Sadducees`},body:{nb:`Trolig oppkalt etter Sadok, Davids prest. Josefus (Jødenes historie 18,16–17) sier de bare hadde de rike med seg, avviste sjelens liv etter døden, og at folket ikke ville høre på dem. De sto nær templet og øversteprestene (Apg 5,17) og holdt fred med Roma. Lukas forklarer for leseren at de «sier at det ikke er noen oppstandelse» (Luk 20,27; Apg 23,8), slik man gjør for en som ikke kjenner landet. De forsvant med templet i år 70. Senere kirkefedre sa at de bare godtok Mosebøkene; Josefus sier bare at de avviste den muntlige tradisjonen. Alle kildene våre om saddukeerne (Josefus, Det nye testamente, rabbinerne) er skrevet av motstandere; ingen saddukeisk tekst er bevart.`,en:`Probably named after Zadok, David’s priest. Josephus (Jewish Antiquities 18.16–17) says they had only the rich with them, denied the soul’s life after death, and that the people would not listen to them. They stood close to the temple and the high priests (Acts 5:17) and kept peace with Rome. Luke explains to the reader that they “say there is no resurrection” (Luke 20:27; Acts 23:8), as one does for someone who does not know the land. They disappeared with the temple in AD 70. Later church fathers said they accepted only the books of Moses; Josephus says only that they rejected the oral tradition. All our sources on the Sadducees (Josephus, the New Testament, the rabbis) were written by opponents; no Sadducean text survives.`},unlockedBy:`fakta:saddukeere`},{id:`essenere`,title:{nb:`Essenerne`,en:`The Essenes`},body:{nb:`Josefus (Krigen 2,119–161), Filon og Plinius beskriver essenerne: felles eiendom, daglige renselsesbad, måltider i stillhet, strenge sabbatsregler, noen ugifte. De fleste forskere knytter dem til samfunnet ved Qumran, der Dødehavsrullene ble funnet fra 1947. Rullene viser forventning om to messiaser (prest og konge), en annen kalender enn templets, og at vanføre var utelukket fra forsamlingen (1QSa 2,5–9). Evangeliene nevner aldri essenerne; forklaringen kan være at de holdt seg for seg selv, og at Jesus ikke møtte dem. Fraværet er et lite tegn på at evangelistene ikke konstruerte motstandere. Navnet «essener» er gresk; rullene kaller seg «yahad», fellesskapet. Krigsrullen fra Qumran (1QM) beskriver en endetidskrig mellom «lysets sønner» og «mørkets sønner». Josefus sier at essenerne bodde spredt i mange byer (Krigen 2,124), ikke bare ved Dødehavet.`,en:`Josephus (War 2.119–161), Philo and Pliny describe the Essenes: common property, daily washings, meals in silence, strict sabbath rules, some unmarried. Most scholars link them to the community at Qumran, where the Dead Sea Scrolls were found from 1947 onwards. The scrolls show an expectation of two Messiahs (priest and king), a different calendar from the temple’s, and that the disabled were excluded from the assembly (1QSa 2:5–9). The Gospels never mention the Essenes; the explanation may be that they kept to themselves, and that Jesus did not meet them. The absence is a small sign that the evangelists did not construct opponents. The name “Essene” is Greek; the community in the scrolls calls itself “yahad”, the community. The War Scroll from Qumran (1QM) describes an end-time war between “the sons of light” and “the sons of darkness”. Josephus says the Essenes lived scattered in many towns (War 2.124), not only by the Dead Sea.`},unlockedBy:`fakta:essenere`},{id:`fjerde`,title:{nb:`Den fjerde retningen`,en:`The fourth school`},body:{nb:`Josefus (Jødenes historie 18,23) kaller Judas fra Galileas tilhengere «den fjerde filosofien»: som fariseerne i lære, men med en «ubøyelig kjærlighet til friheten» og Gud som eneste herre. Ordet «selot» (ivrer) om et organisert parti bruker Josefus først om opprøret fra år 66; at Simon kalles «seloten» blant de tolv (Luk 6,15), betyr trolig «den ivrige». Spørsmålet om skatt til keiseren (Luk 20,20–26) var nettopp dette partiets prøvestein, og Jesu svar ville ha skuffet dem. Josefus’ inndeling i «filosofier» er laget for greske lesere, som kjente stoikere og epikureere. De fleste jøder hørte ikke til noen av dem, og «den fjerde» er Josefus’ egen merkelapp på dem han ville gi skylden for krigen i 66. Judas fra Galilea gjorde opprør da romerne lot folket i Judea telle og skattlegge i år 6 (Apg 5,37; Josefus, Jødenes historie 18,1–10).`,en:`Josephus (Jewish Antiquities 18.23) calls the followers of Judas of Galilee “the fourth philosophy”: like the Pharisees in doctrine, but with an “inviolable love of freedom” and God as the only lord. Josephus first uses the word “Zealot” for an organised party in connection with the revolt of AD 66; that Simon is called “the Zealot” among the twelve (Luke 6:15) probably means “the zealous one”. The question of tax to the emperor (Luke 20:20–26) was exactly this party’s touchstone, and Jesus’ answer would have disappointed them. Josephus’ division into “philosophies” is made for Greek readers, who knew Stoics and Epicureans. Most Jews belonged to none of them, and “the fourth” is Josephus’ own label for those he wanted to blame for the war of 66. Judas of Galilee rebelled when the Romans had the people of Judea counted and taxed in AD 6 (Acts 5:37; Josephus, Jewish Antiquities 18.1–10).`},unlockedBy:`fakta:fjerde`},{id:`samaritanere`,title:{nb:`Samaritanene`,en:`The Samaritans`},body:{nb:`Samaritanene regnet seg som Israels rest i nord, med sitt eget tempel på Garisim (ødelagt av Johannes Hyrkanos ca. 110 f.Kr.) og bare Mosebøkene som Skrift. Jødene så dem som fremmede med blandet opphav (2 Kong 17). Fiendskapet var skarpt: Josefus forteller om samaritaner som spredte knokler i templet, og om drap på galileiske pilegrimer (Jødenes historie 18,30; 20,118). Lukas har tre samaritanfortellinger som ingen andre har: landsbyen som avviste ham (9,51–56), den barmhjertige samaritan (10,25–37) og den spedalske som vendte tilbake (17,11–19). Et lite samaritansk samfunn finnes ennå ved Garisim. Noen jøder gikk omveier for å slippe Samaria, men Josefus sier at galileere pleide å gå gjennom landet på vei til høytidene (Jødenes historie 20,118).`,en:`The Samaritans counted themselves as Israel’s remnant in the north, with their own temple on Gerizim (destroyed by John Hyrcanus c. 110 BC) and only the books of Moses as Scripture. The Jews saw them as foreigners of mixed origin (2 Kgs 17). The enmity was sharp: Josephus tells of Samaritans who scattered bones in the temple, and of killings of Galilean pilgrims (Jewish Antiquities 18.30; 20.118). Luke has three Samaritan stories no one else has: the village that rejected him (9:51–56), the good Samaritan (10:25–37) and the leper who returned (17:11–19). A small Samaritan community still exists by Gerizim. Some Jews took detours to avoid Samaria, but Josephus says Galileans usually went through the land on their way to the feasts (Jewish Antiquities 20.118).`},unlockedBy:`fakta:samaritanere`},{id:`gudfryktige`,title:{nb:`De gudfryktige og gjerdet`,en:`The God-fearers and the barrier`},body:{nb:`Hedninger som trodde på Israels Gud uten å bli omskåret, kalles «gudfryktige» i Apostlenes gjerninger (10,2; 13,16; 17,4); en innskrift fra Afrodisias (trolig 300-tallet eller senere; dateringen er omstridt) lister dem som egen gruppe ved synagogen. I templet stoppet de ved soreg, en lav mur med tavler på gresk og latin som truet enhver fremmed som gikk forbi med døden; to slike tavler er funnet (1871 og 1935). Josefus bekrefter at romerne lot jødene håndheve dette, selv mot romerske borgere (Krigen 6,124–126). Opptøyene mot Paulus (Apg 21,28–29) handlet om nettopp denne muren. Lukas forteller også om en romersk offiser i Kapernaum som hadde bygd synagogen der (Luk 7,1–10).`,en:`Gentiles who believed in the God of Israel without being circumcised are called “God-fearers” in Acts (10:2; 13:16; 17:4); an inscription from Aphrodisias (probably from the fourth century or later; the dating is disputed) lists them as a separate group at the synagogue. In the temple they stopped at the soreg, a low wall with plaques in Greek and Latin threatening with death any foreigner who passed; two such plaques have been found (1871 and 1935). Josephus confirms that the Romans let the Jews enforce this, even against Roman citizens (War 6.124–126). The riot against Paul (Acts 21:28–29) was about precisely this wall. Luke also tells of a Roman officer in Capernaum who had built the synagogue there (Luke 7:1–10).`},unlockedBy:`fakta:gudfryktige`},{id:`svaret-fra-tornebusken`,title:{nb:`Svaret fra tornebusken`,en:`The answer from the burning bush`},body:{nb:`Saddukeerne godtok ikke oppstandelsen og la mest vekt på Mosebøkene. Jesus svarer dem derfor fra 2 Mos 3,6, der Gud kaller seg Abrahams, Isaks og Jakobs Gud lenge etter at de var døde: han er de levendes Gud (Luk 20,27–38). Lukas tar med at noen av de skriftlærde sa «godt svart, Mester» (Luk 20,39), en av de få gangene motstandere gir ham rett, og han lar det stå.`,en:`The Sadducees did not accept the resurrection and put most weight on the books of Moses. So Jesus answers them from Exod 3:6, where God calls himself the God of Abraham, Isaac and Jacob long after they had died: he is the God of the living (Luke 20:27–38). Luke includes that some of the scribes said “well answered, Teacher” (Luke 20:39), one of the few times opponents agree with him, and he lets it stand.`},unlockedBy:`oppstandelsen-lost`},{id:`diktet`,title:{nb:`Hva er funnet på i denne episoden?`,en:`What is made up in this episode?`},body:{nb:`Alle du møter i forgården og i rådskammeret, er funnet på, og det samme er det de sier. At Lukas snakket med Josefus, er også funnet på; vi vet ikke om de to noen gang møttes. Josefus skrev om de fire retningene mange år senere: i «Den jødiske krig» (bok 2, omkring år 75) og i «Jødenes historie» (bok 18, omkring år 93). Det spillet prøver, er om bildet hos Lukas stemmer med bildet hos Josefus. Setet til Nikodemus og benkene i rådskammeret er også laget for spillet.`,en:`Everyone you meet in the forecourt and in the council chamber is made up, and so is what they say. That Luke talked with Josephus is made up too; we do not know whether the two ever met. Josephus wrote about the four schools many years later: in The Jewish War (book 2, around AD 75) and in Jewish Antiquities (book 18, around AD 93). What the game tests is whether Luke’s picture matches the one in Josephus. Nicodemus’ seat and the benches in the council chamber are also made for the game.`},unlockedBy:`mot-josefus-lost`}],words:[{id:`fariseeren`,kind:`person`,text:{nb:`fariseeren`,en:`the Pharisee`},form:`m`,unlockedBy:`spor:fariseer`},{id:`saddukeeren`,kind:`person`,text:{nb:`saddukeeren`,en:`the Sadducee`},form:`m`,unlockedBy:`spor:saddukeer`},{id:`esseneren`,kind:`person`,text:{nb:`esseneren`,en:`the Essene`},form:`m`,unlockedBy:`spor:essener`},{id:`den-unge`,kind:`person`,text:{nb:`den unge ved porten`,en:`the young man at the gate`},form:`m`,unlockedBy:`spor:ung`},{id:`tolleren`,kind:`person`,text:{nb:`tolleren`,en:`the tax collector`},form:`m`,unlockedBy:`spor:toller`},{id:`raadsherren`,kind:`person`,text:{nb:`rådsherren`,en:`the councillor`},form:`m`,unlockedBy:`spor:raadsherre`},{id:`en-samaritan`,kind:`person`,text:{nb:`en samaritan`,en:`a Samaritan`},form:`m`,unlockedBy:`spor:samaritan`},{id:`en-prest`,kind:`person`,text:{nb:`en prest`,en:`a priest`},form:`m`,unlockedBy:`spor:essener`},{id:`en-fariseer`,kind:`person`,text:{nb:`en fariseer`,en:`a Pharisee`},form:`m`,unlockedBy:`spor:nikodemus`},{id:`nikodemus`,kind:`person`,text:{nb:`Nikodemus`,en:`Nicodemus`},form:`m`,unlockedBy:`spor:nikodemus`},{id:`paulus`,kind:`person`,text:{nb:`Paulus`,en:`Paul`},form:`m`,unlockedBy:`spor:raadsherre`},{id:`tollere`,kind:`person`,text:{nb:`tollere`,en:`tax collectors`},form:`pl`,unlockedBy:`spor:fariseer`},{id:`saddukeere`,kind:`person`,text:{nb:`saddukeere`,en:`Sadducees`},form:`pl`},{id:`oversteprestene`,kind:`person`,text:{nb:`øversteprestene`,en:`the chief priests`},form:`pl`,unlockedBy:`spor:raadsherre`},{id:`de-eldste`,kind:`person`,text:{nb:`de eldste`,en:`the elders`},form:`pl`,unlockedBy:`spor:raadsherre`},{id:`fariseerne`,kind:`person`,text:{nb:`fariseerne`,en:`the Pharisees`},form:`pl`,unlockedBy:`spor:raadsherre`},{id:`saddukeerne`,kind:`person`,text:{nb:`saddukeerne`,en:`the Sadducees`},form:`pl`,unlockedBy:`spor:josefus`},{id:`essenerne`,kind:`person`,text:{nb:`essenerne`,en:`the Essenes`},form:`pl`,unlockedBy:`spor:notat`},{id:`moses-boker`,kind:`ting`,text:{nb:`Moses’ bøker`,en:`the books of Moses`},form:`pl`,unlockedBy:`spor:moses`},{id:`profetene`,kind:`ting`,text:{nb:`profetene`,en:`the prophets`},form:`pl`,unlockedBy:`spor:moses`},{id:`salmene`,kind:`ting`,text:{nb:`salmene`,en:`the psalms`},form:`pl`,unlockedBy:`spor:moses`},{id:`tornebusken`,kind:`ting`,text:{nb:`tornebusken`,en:`the burning bush`},form:`m`,unlockedBy:`spor:saddukeer`},{id:`danielrullen`,kind:`ting`,text:{nb:`rullen med Daniel`,en:`the scroll of Daniel`},form:`m`,unlockedBy:`spor:daniel`},{id:`mynten`,kind:`ting`,text:{nb:`mynten`,en:`the coin`},form:`m`,unlockedBy:`spor:ung`},{id:`samaritanen`,kind:`person`,form:`m`,text:{nb:`samaritanen`,en:`the Samaritan`},unlockedBy:`spor:samaritan`},{id:`levi`,kind:`person`,form:`m`,text:{nb:`Levi`,en:`Levi`},unlockedBy:`spor:toller`},{id:`teofilos`,kind:`person`,form:`m`,text:{nb:`Teofilos`,en:`Theophilus`},unlockedBy:`spor:greker`}],deductions:[{id:`fire`,question:{nb:`Hvem er de fire flokkene, og hvem av dem har forlatt templet?`,en:`Who are the four groups, and which has left the temple?`},report:[{text:{nb:`{1} sier at oppstandelsen ikke står hos Moses, og {2} holder seg borte fra templet.`,en:`{1} says the resurrection is not in Moses, and {2} keeps away from the temple.`},gaps:[{choices:[`saddukeeren`,`fariseeren`,`den-unge`]},{choices:[`esseneren`,`samaritanen`,`saddukeeren`]}],hint:{nb:`Samaritanens tempel ble revet. Hvem sa at oppstandelsen ikke står hos Moses, og hvem sa «vi har forlatt templet»?`,en:`The Samaritan’s temple was torn down. Who said the resurrection is not in Moses, and who said “we have left the temple”?`}},{text:{nb:`{1} har folket med seg, og {2} vil gripe til sverdet mot keiseren.`,en:`{1} has the people behind him, and {2} wants to fight the emperor.`},gaps:[{choices:[`fariseeren`,`esseneren`,`tolleren`]},{choices:[`den-unge`,`saddukeeren`,`tolleren`]}],hint:{nb:`Hvem sa at folket hører på dem, og hvem venter på dagen de tar sverdet?`,en:`Who said the people listen to them, and who waits for the day they take the sword?`}}],checks:[`selv`,`flere`,`tidlig`],done:{nb:`Uenige om nesten alt: hva som er Skrift, om de døde står opp, hvem som er ren, og hva man gjør med Roma.`,en:`They disagree on nearly everything: Scripture, the dead rising, who is clean, what to do about Rome.`},set:[`fire-lost`]},{id:`oppstandelsen`,question:{nb:`Hvorfor krangler de om oppstandelsen, og hva svarte Jesus med?`,en:`Why the quarrel over the resurrection, and what did Jesus answer with?`},report:[{text:{nb:`Striden gjelder hva som er Skrift: saddukeerne holder seg til {1}.`,en:`The quarrel is over what Scripture is: the Sadducees keep to {1}.`},gaps:[{choices:[`moses-boker`,`profetene`,`salmene`]}],hint:{nb:`Les rullene i skriverkammeret: hva godtar hvem?`,en:`Read the scrolls in the scribe’s chamber: who accepts what?`}},{text:{nb:`Jesus svarte dem med {1}, og de ble stille.`,en:`Jesus answered with {1}, and they fell silent.`},gaps:[{choices:[`tornebusken`,`danielrullen`,`mynten`]}],hint:{nb:`Hva sa saddukeeren om svaret de fikk?`,en:`What did the Sadducee say about the answer they got?`}}],checks:[`selv`,`flere`,`tidlig`],done:{nb:`Han svarte saddukeerne fra Moses, der de selv sto. Derfor veide svaret så tungt.`,en:`He answered the Sadducees from Moses, where they themselves stood. So the answer carried weight.`},set:[`oppstandelsen-lost`]},{id:`de-andre`,question:{nb:`Hvem står utenfor alle fire flokkene, og hvordan møtte Jesus dem?`,en:`Who stands outside all four groups, and how did Jesus meet them?`},report:[{text:{nb:`Jesus satte seg til bords hos {1}, og fariseerne ville vite hvorfor.`,en:`Jesus sat down to eat with {1}, and the Pharisees wanted to know why.`},gaps:[{choices:[`levi`,`en-samaritan`,`nikodemus`]}],hint:{nb:`Han spiste hos fariseere og hos tollere. Men i hvilket hus spurte fariseerne hvorfor?`,en:`He ate with Pharisees and with tax collectors. But in whose house did the Pharisees ask why?`}},{text:{nb:`Han lot {1} være helten da han lærte om å elske nesten.`,en:`He made {1} the hero when he taught about loving your neighbour.`},gaps:[{choices:[`en-samaritan`,`en-prest`,`en-fariseer`]}],hint:{nb:`Hva fortalte samaritanen om historien?`,en:`What did the Samaritan tell about the story?`}},{text:{nb:`Ved gjerdet må grekeren stoppe, og {1} er vel en av dem.`,en:`At the barrier the Greek must stop, and {1} may well be one of them.`},gaps:[{choices:[`teofilos`,`paulus`,`nikodemus`]}],hint:{nb:`Hvem sa grekeren var «en av oss»?`,en:`Who did the Greek say was “one of us”?`}}],checks:[`selv`,`flere`],done:{nb:`At han spiste med tollere, forteller mange. Historien om samaritanen har bare jeg.`,en:`Many tell that he ate with tax collectors. The story of the Samaritan, only I have.`},set:[`de-andre-lost`]},{id:`mot-josefus`,question:{nb:`Stemmer det Lukas’ vitner forteller, med det Josefus forteller?`,en:`Does what Luke’s witnesses say fit Josephus?`},report:[{text:{nb:`Hos Josefus avviser {1} at sjelen lever videre, akkurat som i forgården.`,en:`In Josephus, {1} deny that the soul lives on, as in the court.`},gaps:[{choices:[`saddukeerne`,`fariseerne`,`essenerne`]}],hint:{nb:`Les Josefus’ oversikt: hvem avviser hva?`,en:`Read Josephus’ overview: who rejects what?`}},{text:{nb:`{1} fortalte at Paulus splittet rådet med ett ord.`,en:`{1} told that Paul split the council with one word.`},gaps:[{choices:[`raadsherren`,`saddukeeren`,`tolleren`]}],hint:{nb:`Hvem nevnte Paulus i dag?`,en:`Who mentioned Paul today?`}},{text:{nb:`Og {1} nevnes aldri hos meg.`,en:`And {1} never appear in my account.`},gaps:[{choices:[`essenerne`,`oversteprestene`,`de-eldste`]}],hint:{nb:`Les notatet mitt.`,en:`Read my note.`}}],checks:[`selv`,`flere`,`alt`],done:{nb:`Samme partier, samme strid. Hadde jeg diktet dette langt herfra, hadde jeg neppe truffet så godt.`,en:`Same parties, same quarrel. Had I made this up far away, I would hardly have got it so right.`},set:[`mot-josefus-lost`]},{id:`passet-ikke`,question:{nb:`Hvilken flokk hørte Jesus til? Hvem nekter spedalske plass ved bordet?`,en:`Which group was Jesus in? Who refuses lepers a place at the table?`},report:[{text:{nb:`{1} holder seg borte fra alt urent, men han rørte ved spedalske.`,en:`{1} shuns everything unclean, but he touched lepers.`},gaps:[{choices:[`esseneren`,`fariseeren`,`tolleren`]}],hint:{nb:`Fariseeren holder hendene rene. Men hvem sa at en spedalsk ikke får sitte ved bordet?`,en:`The Pharisee keeps his hands clean. But who said a leper may not sit at the table?`}},{text:{nb:`Skatten til keiseren skilte ham fra {1}.`,en:`The tax to the emperor set him apart from {1}.`},gaps:[{choices:[`den-unge`,`saddukeeren`,`tolleren`]}],hint:{nb:`Hvem sa at skatt til keiseren er å kalle ham herre?`,en:`Who said paying tax to the emperor means calling him lord?`}},{text:{nb:`Han sa til {1} at de bare vasket utsiden av begeret.`,en:`He told {1} that they only washed the outside of the cup.`},gaps:[{choices:[`fariseeren`,`esseneren`,`saddukeeren`]}],hint:{nb:`Hvem sa «det sved»?`,en:`Who said “that stung”?`}}],checks:[`selv`,`flere`,`tidlig`,`alt`],done:{nb:`Han hørte ikke til noen flokk. Ingen av dem kunne ha laget denne Messias. Det er én grunn til at jeg stoler på vitnene.`,en:`He belonged to no group. None of them could have made this Messiah. One reason I trust the witnesses.`},set:[`passet-ikke-lost`]},{id:`raadet`,question:{nb:`Hvem i rådet sto bak dommen, og hvem av dem var delt?`,en:`Who in the council backed the verdict, and who among them was divided?`},report:[{text:{nb:`{1} ledet saken mot ham, redde for å miste templet.`,en:`{1} led the case against him, afraid of losing the temple.`},gaps:[{choices:[`oversteprestene`,`fariseerne`,`tollere`]}],hint:{nb:`Hva sa rådsherren om morgenen de dømte ham?`,en:`What did the councillor say about the morning they condemned him?`}},{text:{nb:`{1} ba rådet høre ham før det dømte.`,en:`{1} asked the council to hear him before it judged.`},gaps:[{choices:[`nikodemus`,`paulus`,`raadsherren`]}],hint:{nb:`Se på setet i rådskammeret.`,en:`Look at the seat in the council chamber.`}},{text:{nb:`Om {1} sier jeg ikke at alle sto bak dommen.`,en:`Of {1} I do not say all backed the verdict.`},gaps:[{choices:[`fariseerne`,`de-eldste`,`oversteprestene`]}],hint:{nb:`Hva var rådsherren usikker på?`,en:`What was the councillor unsure about?`}}],checks:[`selv`,`flere`,`tidlig`],open:{nb:`Hvor mange i rådet som var med på dommen, kan jeg ikke avgjøre. Noen hadde advart ham.`,en:`How many in the council backed the verdict, I cannot settle. Some had warned him.`},done:{nb:`Prestene førte an, og fariseerne var delt. Derfor skriver jeg ikke «fariseerne» som om det gjaldt alle.`,en:`The priests led; the Pharisees were divided. So I do not write “the Pharisees” as if all were alike.`},set:[`raadet-lost`]}],objectives:[{text:{nb:`Snakk med Lukas`,en:`Talk to Luke`},doneBy:[`oppdrag`]},{text:{nb:`Snakk med fariseeren, saddukeeren, esseneren og den unge ved porten`,en:`Talk to the Pharisee, the Sadducee, the Essene and the young man at the gate`},doneBy:[`spor:fariseer`,`spor:saddukeer`,`spor:essener`,`spor:ung`]},{text:{nb:`Snakk med tolleren, samaritanen og grekeren, og se på gjerdet`,en:`Talk to the tax collector, the Samaritan and the Greek, and look at the barrier`},doneBy:[`spor:toller`,`spor:samaritan`,`spor:greker`,`spor:gjerdet`]},{text:{nb:`Gå inn i rådskammeret: hør rådsherren, se benkene og Nikodemus’ sete`,en:`Go into the council chamber: hear the councillor, see the benches and Nicodemus’ seat`},doneBy:[`spor:raadsherre`,`spor:benker`,`spor:nikodemus`]},{text:{nb:`Løs de fire sakene om flokkene og rådet`,en:`Solve the four cases about the groups and the council`},doneBy:[`fire-lost`,`de-andre-lost`,`passet-ikke-lost`,`raadet-lost`]},{text:{nb:`Gå inn i skriverkammeret, les arkene og rullene, og sorter hvem som sier hva`,en:`Go into the scribe’s chamber, read the sheets and scrolls, and sort who says what`},doneBy:[`spor:josefus`,`spor:notat`,`spor:moses`,`spor:daniel`,`retningene-sortert`]},{text:{nb:`Løs de to siste sakene`,en:`Solve the last two cases`},doneBy:[`oppstandelsen-lost`,`mot-josefus-lost`]},{text:{nb:`Gå tilbake til Lukas`,en:`Go back to Luke`},doneBy:[`avsluttet`]}],rewards:[{flag:`fire-lost`,points:15,label:{nb:`Skill de fire flokkene`,en:`Tell the four groups apart`}},{flag:`oppstandelsen-lost`,points:15,label:{nb:`Forstå striden om oppstandelsen`,en:`Understand the dispute about the resurrection`}},{flag:`de-andre-lost`,points:15,label:{nb:`Finn dem utenfor`,en:`Find the outsiders`}},{flag:`mot-josefus-lost`,points:10,label:{nb:`Prøv vitnene mot Josefus`,en:`Test the witnesses against Josephus`}},{flag:`passet-ikke-lost`,points:20,label:{nb:`Se at han ikke passet`,en:`See that he did not fit`}},{flag:`raadet-lost`,points:10,label:{nb:`Forstå det store rådet`,en:`Understand the great council`}},{flag:`avsluttet`,points:10,label:{nb:`Fullfør dagen med Lukas`,en:`Finish the day with Luke`}},{flag:`spill-stjerner`,points:10,label:{nb:`Finn stjernene`,en:`Find the stars`},side:!0},{flag:`ingen-kom`,points:12,label:{nb:`Bær tollerens innbydelser til alle fire`,en:`Carry the tax collector’s invitations to all four`},side:!0},{flag:`kalender-sett`,points:10,label:{nb:`Se på soluret og månetavla`,en:`Look at the sundial and the moon table`},side:!0},{flag:`retningene-sortert`,points:10,label:{nb:`Sorter de fire retningene`,en:`Sort the four schools`},side:!0}],inventory:[{icon:`✉`,label:{nb:`Innbydelser`,en:`Invitations`},flags:[`innbydelser`],goneWhen:`ingen-kom`}],ambience:[{sound:`market`,x:20,y:13,radius:6},{sound:`garden`,x:5,y:15,radius:6}],goal:[`avsluttet`],solution:`lukas.fariseer.saddukeer.essener.ung.toller.passet-ikke.toller.fariseer.saddukeer.essener.ung.toller.samaritan.fire.greker.gutt.gjerdet.soluret.maanetavla.essener.dor-raadskammer.raadsherre.benker.nikodemus.de-andre.raadet.dor-ut-raadskammer.dor-skriverkammer.notat.josefus.mot-josefus.moses.daniel.oppstandelsen.dor-ut-skriverkammer.lukas`.split(`.`)};export{e as default};